+                      "lang": "%s",
+                      "source": "false_script"
+                    }
+                  }
+                },
+                {
+                  "set": {
+                    "tag": "set-c",
+                    "field": "c",
+                    "value": "3",
+                    "ignore_failure": true
+                  }
+                },
+                {
+                  "set": {
+                    "tag": "set-d",
+                    "field": "d",
+                    "value": "4",
+                    "if": {
+                      "lang": "%s",
+                      "source": "true_script"
+                    },
+                    "ignore_failure": true
+                  }
+                }
