+                        }
+                    }
+
+                    @Override
+                    public void onFailure(Exception e) {
+                        // should not happen
+                        logger.error(() -> Strings.format("[%s] task %s failed", taskRunnerName, task), e);
+                        assert false : e;
+                        task.onFailure(e);
+                    }
+
+                    @Override
+                    protected void doRun() {
+                        logger.trace("[{}] running task {}", taskRunnerName, task);
